/**
 * Documentation generated by Gemini
 * File Name: LotteryScreen.kt
 * Purpose: Dual-purpose screen displaying either the lotteries created and managed by the campsite owner
 * (with deletion options) or the lotteries joined by an entrant (with leave and reserve options upon winning).
 * Architectural Role: View layer in MVVM architecture for lottery management and participation.
 * Outstanding Issues:
 * - None currently.
 */
package com.example.campsitelottery

import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.RectangleShape
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.platform.testTag
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.navigation.NavController
import com.google.firebase.firestore.FirebaseFirestore
import java.util.Date

/**
 * Documentation generated by Gemini
 * Composable screen displaying lotteries filtered by owner management or entrant participation.
 *
 * @param navController Navigation controller for routing.
 * @param isOwnerView True if opened from the owner dashboard to manage lotteries; false for entrants.
 */
@Composable
fun LotteryScreen(
    navController: NavController,
    isOwnerView: Boolean = false
) {
    val context = LocalContext.current
    val deviceId = DeviceIdentity.getDeviceId(context)

    var waitlists by remember { mutableStateOf(listOf<Waitlist>()) }
    var isLoading by remember { mutableStateOf(true) }

    // Fetch waitlists based on whether we are in owner view or entrant view
    LaunchedEffect(deviceId, isOwnerView) {
        val db = FirebaseFirestore.getInstance()
        val query = if (isOwnerView) {
            db.collection("waitlists").whereEqualTo("ownerId", deviceId)
        } else {
            db.collection("waitlists").whereArrayContains("joinedEntrantIds", deviceId)
        }

        query.addSnapshotListener { snapshot, error ->
            if (error != null) {
                isLoading = false
                return@addSnapshotListener
            }
            if (snapshot != null) {
                val waitlistsList = snapshot.documents.mapNotNull { it.toObject(Waitlist::class.java) }

                // If viewing as owner, check if any active lotteries have passed their registration date
                if (isOwnerView) {
                    waitlistsList.forEach { waitlist ->
                        checkAndExecuteAutomatedDraw(waitlist)
                    }
                }

                waitlists = waitlistsList
                isLoading = false
            }

        }

    }

    Column(
        modifier = Modifier.fillMaxSize().padding(16.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RectangleShape,
                modifier = Modifier.testTag("toBackButton")
            ) {
                Text("Back")
            }

            // Quick access button to create a new lottery if viewing as owner
            if (isOwnerView) {
                Button(
                    onClick = { navController.navigate("createLottery") },
                    shape = RectangleShape
                ) {
                    Text("+ Create Lottery")
                }
            }
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text(
            text = if (isOwnerView) "My Managed Lotteries" else "My Joined Lotteries",
            fontSize = 28.sp
        )
        Spacer(modifier = Modifier.height(16.dp))

        when {
            isLoading -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator()
                }
            }
            waitlists.isEmpty() -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text(
                        text = if (isOwnerView) "You haven't created any lotteries yet." else "You haven't joined any lotteries yet.",
                        fontSize = 16.sp
                    )
                }
            }
            else -> {
                LazyColumn(
                    modifier = Modifier.fillMaxWidth().weight(1f),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    items(waitlists) { waitlist ->
                        Card(modifier = Modifier
                            .fillMaxWidth()
                            .padding(vertical = 4.dp)
                            .let { modifier ->
                                if( isOwnerView){
                                    modifier.clickable(){
                                        navController.navigate("createLottery/${waitlist.waitlistId}")
                                    }
                                } else {
                                    Modifier
                                }
                            }
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                val title = if (waitlist.lotteryName.isNotBlank()) waitlist.lotteryName else "Campsite Lottery Pool"
                                Text(text = title, fontSize = 20.sp)
                                Spacer(modifier = Modifier.height(4.dp))
                                Text(text = "Campsites included: ${waitlist.campsiteIds.size}", fontSize = 14.sp)
                                Text(text = "Winners to draw: ${waitlist.numberOfWinnersToDraw}", fontSize = 14.sp)

                                Spacer(modifier = Modifier.height(8.dp))

                                if (isOwnerView) {
                                    // --- OWNER VIEW MODE ---
                                    val status = if (waitlist.isDrawn) {
                                        "Status: Drawn (${waitlist.selectedWinnerIds.size} winners selected)"
                                    } else {
                                        "Status: Active / Waiting for Draw (${waitlist.joinedEntrantIds.size} entrants)"
                                    }
                                    Text(text = status, fontSize = 14.sp)

                                    Spacer(modifier = Modifier.height(12.dp))
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.End
                                    ) {
                                        Button(
                                            onClick = {
                                                FirebaseFirestore.getInstance().collection("waitlists")
                                                    .document(waitlist.waitlistId)
                                                    .delete()
                                            },
                                            colors = ButtonDefaults.buttonColors(containerColor = Color.Red),
                                            shape = RectangleShape,
                                            modifier = Modifier.testTag("deleteLotteryButton_${waitlist.waitlistId}")
                                        ) {
                                            Text("Delete Lottery", color = Color.White)
                                        }
                                        Button(
                                            onClick = { navController.navigate("entrantList/${waitlist.waitlistId}") },
                                            shape = RectangleShape
                                        ) {
                                            Text("View Entrants")
                                        }

                                    }
                                } else {
                                    // --- ENTRANT / USER VIEW MODE ---
                                    val isWinner = waitlist.selectedWinnerIds.contains(deviceId)
                                    val statusText = when {
                                        !waitlist.isDrawn -> "STATUS: Waiting for Draw"
                                        isWinner -> "STATUS: YOU WON! 🎉"
                                        else -> "STATUS: Not Selected"
                                    }
                                    Text(text = statusText, fontSize = 16.sp)

                                    Spacer(modifier = Modifier.height(12.dp))
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.End
                                    ) {
                                        // Option to leave waitlist if draw has not happened yet
                                        if (!waitlist.isDrawn) {
                                            Button(
                                                onClick = {
                                                    val updatedEntrants = waitlist.joinedEntrantIds.toMutableList().apply { remove(deviceId) }
                                                    FirebaseFirestore.getInstance().collection("waitlists")
                                                        .document(waitlist.waitlistId)
                                                        .update("joinedEntrantIds", updatedEntrants)
                                                },
                                                shape = RectangleShape
                                            ) {
                                                Text("Leave")
                                            }
                                            Spacer(modifier = Modifier.width(8.dp))
                                        }

                                        // Option to Reserve if the user won and the draw is complete
                                        if (isWinner && waitlist.isDrawn) {
                                            Button(
                                                onClick = { navController.navigate("reservation") },
                                                shape = RectangleShape,
                                                modifier = Modifier.testTag("toReservationButton_${waitlist.waitlistId}")
                                            ) {
                                                Text("Reserve")
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

/**
 * Function Made by Gemini
 * Automatically evaluates whether the registration period has ended and
 * executes the random winner draw if it hasn't been drawn yet.
 */
private fun checkAndExecuteAutomatedDraw(waitlist: Waitlist) {
    val currentDate = Date()
    // Check if registration end date has passed and the lottery is not yet drawn
    if (waitlist.registrationEndDate != null &&
        currentDate.after(waitlist.registrationEndDate) &&
        !waitlist.isDrawn &&
        waitlist.joinedEntrantIds.isNotEmpty()) {

        val shuffledEntrants = waitlist.joinedEntrantIds.shuffled() // randomizes
        val winners = shuffledEntrants.take(waitlist.numberOfWinnersToDraw) // selects winners

        FirebaseFirestore.getInstance().collection("waitlists")
            .document(waitlist.waitlistId)
            .update(
                mapOf(
                    "selectedWinnerIds" to winners,
                    "isDrawn" to true
                )
            )
    }
}
